import json, importlib.util, sys
spec=importlib.util.spec_from_file_location("gscore","verl/utils/reward_score/gsm8k.py")
m=importlib.util.module_from_spec(spec); spec.loader.exec_module(m)
for step in [0,10,30,60]:
    rows=[json.loads(l) for l in open(f'results/grpo_gsm8k_seed42/val_generations/{step}.jsonl')]
    mism=0; ex=[]
    for r in rows:
        s=m.compute_score(r['output'], r['gts'], method='flexible')
        if float(s)!=float(r['score']):
            mism+=1
            if len(ex)<8: ex.append((r['gts'], r['score'], s, r['output'][-120:]))
    print(f"step {step}: mismatches {mism}/{len(rows)}; recorded mean {sum(r['score'] for r in rows)/len(rows):.6f}; recomputed mean {sum(m.compute_score(r['output'],r['gts'],method='flexible') for r in rows)/len(rows):.6f}")
    for e in ex[:4]: print("   ", e)
EOF

