python3 -I - <<'EOF'
import json, re
rows=[json.loads(l) for l in open('results/grpo_gsm8k_seed42/val_generations/60.jsonl')]
def lastbox(s):
    m=re.findall(r"\\boxed\{([^{}]*)\}", s); return m[-1].strip() if m else None
spur=[]
for r in rows:
    if r['score']==1:
        b=lastbox(r['output'])
        if b is not None and b.replace(',','').strip()!=r['gts']:
            spur.append(r)
print("score=1 with an explicit final boxed answer different from gt:", len(spur), "of", sum(1 for r in rows if r['score']==1))
for r in spur[:8]:
    print('='*90); print("gt",r['gts'],"boxed",lastbox(r['output'])); print(r['output'][-230:].replace('\n',' | '))
# also count score=1 with no explicit final answer at all (ends with reasoning)
EOF

